import type { ChapterSaga } from '../types';

// Chapter III — The Drowned Docks. Vellmoor harbour, at a tide that never turned.
// Speakers: wren = Corvin, odile = Seraphine, bastian = Columbine, marigold = Valerian,
// ichabod = Lucien, evangeline = Aveline Halcyon. Plain names are side characters without art.
// 'Keeper Brine' (the Dimmed boss) resolves to the enemy portrait; 'Tobias Brine' is the man himself.
// Refrains: the sea’s breath (“In. And out.”), “only late”, “come home by the stars”,
// “two short and a long”, “nothing sails, nothing sinks”, “count them in”, and the wall-song
// of the Lantern Tide (“Float out, float out, my paper light…”).

export const SAGA_CH3: ChapterSaga = {
  cinematics: [
    // ───────────────────────────────────────────── Opening
    {
      id: 'ch3_open', name: 'Chapter III · The Drowned Docks', bg: 'docks', tone: 'cold',
      clock: '23:10',
      shots: [
        { kind: 'title', kicker: 'CHAPTER III', title: 'The Drowned Docks', sub: 'Vellmoor harbour · the ebb that stayed' },
        { kind: 'narrate', text: 'Vellmoor was built with its face to the sea, the way a house is built with its windows towards the road someone is expected home on. Every street in the old town leans downhill, like a listener. Every one of them ends in salt.' },
        { kind: 'narrate', text: 'For three hundred years the harbour breathed twice a day. In. And out. The fishwives set their kettles by it. The Fishgate bell rang every turning. Children were born on the flood and buried on the ebb, and none of them thought to listen — as no one listens to a heart until it skips.' },
        { kind: 'narrate', text: 'On the last night of 1929 the tide was going out. A spring ebb, the almanacs said — the lowest of the year, drawn thin by a new moon nobody could see. The harbourmaster had chalked it on the board outside his office in his own square hand: LOW WATER, 00:00.' },
        { kind: 'narrate', text: 'Out past the harbour bar, eleven ships were steaming home for the New Year. On the north wall the families stood with paper lanterns, a name lettered on each, waiting for the ebb to take them. A boy in a sailor’s coat stood a little apart, hands in his pockets, lips already moving.' },
        { kind: 'narrate', text: 'They sang what Vellmoor has always sung at the Lantern Tide — a tune older than the wall, flat and patient as the water it was sung to.' },
        { kind: 'narrate', text: 'Float out, float out, my paper light,\nfloat out across the bar,\nand tell the ones the sea has kept\nwe know just where they are.' },
        { kind: 'narrate', text: 'And if they ask how long we’ll watch,\nhow long the wall will stay —\nsay, till the tide forgets to turn.\nAnd that will be no day.' },
        { kind: 'bell', strokes: 12, text: 'Across the water, high on its hill, the Cathedral Clock began to count out midnight.' },
        { kind: 'bell', strokes: 1, ominous: true, text: '…and, where there should have been silence, struck once more.' },
        { kind: 'narrate', text: 'The sea reached the very bottom of its breath. And did not take another.' },
        { kind: 'bg', bg: 'docks', tone: 'cold' },
        { kind: 'narrate', text: 'A year later the water has not come back. The harbour is a bowl of grey mud a mile across, ribbed with the shapes of currents stopped mid-sentence. Ships lie on their sides in it like cattle asleep in a field, their masts pointing at nothing in particular.' },
        { kind: 'narrate', text: 'The smell is the first thing. Not rot — the Dimming does not let things rot, any more than it lets them live. It is the smell of a shell held too long to the ear. Salt, and the memory of salt.' },
        { kind: 'narrate', text: 'And out on the breakwater, at the end of a mile of black stone, the old light still burns. But its beam has turned round. Where it passes, the fog does not glow. It darkens, as if the lamp were pouring night over the water by the bucket, and the sea were too tired to refuse it.' },
        { kind: 'narrate', text: 'The Lantern Keeper came down the Fishgate Stairs at ten past eleven, by a watch that had not been right for a year. Behind him came an oracle with folded wings, a marionette counting under her breath, and a count in a crimson coat who was taking the stairs as a personal insult.' },
        { kind: 'line', who: 'marigold', text: 'One hundred and twelve steps. I counted. A man of my years and my tailoring ought to be carried down to the sea on a litter, by bearers who are being paid far too much and know it.' },
        { kind: 'line', who: 'bastian', text: 'One hundred and thirteen. You missed the one with the gull on it.' },
        { kind: 'line', who: 'marigold', text: 'I did not miss it, mademoiselle. I declined to acknowledge it. The gull was staring.' },
        { kind: 'line', who: 'wren', text: 'Quiet, both of you. Listen.' },
        { kind: 'narrate', text: 'They listened. A harbour is never silent: it creaks, it slaps, it clinks its chains, it grumbles in its sleep like an old dog by a fire. This one made no sound at all. The gulls on the chimney pots sat with their beaks half open, as if someone had lifted the cry from their throats and forgotten to put it back.' },
        { kind: 'line', who: 'odile', text: 'I knew from the letter that the water had stopped. I did not know it would feel like this. Like standing at a bedside where someone has stopped breathing, and nobody has yet found the courage to say so aloud.' },
        { kind: 'line', who: 'bastian', text: 'Is that the sea? All that grey? I thought the sea would be bluer. And louder. And… taller, somehow.' },
        { kind: 'line', who: 'wren', text: 'It was all of those things. It’s only waiting.' },
        { kind: 'line', who: 'bastian', text: 'Waiting for what?' },
        { kind: 'line', who: 'wren', text: 'For midnight to finish.' },
        { kind: 'narrate', text: 'At the foot of the stairs stood the harbourmaster’s office: a narrow brick house with a herring for a weathervane and a slate board by the door. The slate had been wiped and rewritten so often it had worn as pale as a palm. Every column said the same. LOW WATER. 00:00. LOW WATER. 00:00.' },
        { kind: 'narrate', text: 'The door stood ajar. Inside, a lamp burned low over a desk drowned in charts, and a big man in a pea-coat sat with his back to the door, writing one word over and over on the bare wood of the desk, in chalk — the way a tide writes the same line on a beach.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Lucien. Lucien. Lucien Marée. My son. Lucien.' },
        { kind: 'line', who: 'wren', text: 'Harbourmaster? My name is Corvin Vesper. You wrote to me. The crows brought your letter to Corvid Lane, and it still smelled of salt.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Did I? …Yes. Yes, I did. I write a great many letters, Mr. Vesper, and forget most of them before the ink is dry. That one I sealed quickly, so it couldn’t forget me back.' },
        { kind: 'narrate', text: 'He turned. A broad, weathered face, the kind that has squinted into wind for forty years — and behind it a strange thinness, like a photograph left too long in a sunny window. The Dimming had found him. It had not yet finished with him.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'You’ll forgive the desk. My son’s name keeps sliding off the inside of my head, so I write it on the outside of things. Doors. Cuffs. The back of my hand. The desk has been very patient with me.' },
        { kind: 'line', who: 'odile', text: 'Harbourmaster. How much do you still remember?' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'The tide tables for every day of forty years. The draught of every hull that ever tied up in this harbour. The price of herring in the spring of 1903, which was a scandal.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Not my wife’s name. Not since the spring. I look at her picture and I know I loved her — the way you know a song you can no longer hum. The tune goes. The ache of it stays where the tune was.' },
        { kind: 'narrate', text: 'Above the desk hung a photograph: a woman at the tiller of a small, sharp-nosed boat, laughing at whoever held the camera, her hair blown sideways across her mouth. The brass plate on the frame had been rubbed blank by a thumb that kept trying to read it.' },
        { kind: 'line', who: 'marigold', text: 'A pilot boat. I know the lines of her. She took the big ships in over the bar, in all weathers. That is not work for the faint of heart.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'No. She was never that. The Petrel — that was the boat. I remember the boat’s name, Count. Isn’t that a cruel thing? I remember the boat, and not the woman at the tiller.' },
        { kind: 'line', who: 'wren', text: 'Where is your son now?' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Where he always is. At the end of the north wall, calling a sea that will not come.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Go gently with him, Lantern Keeper. He thinks it is his fault. He was born to call the tide, and the tide stopped listening. A boy like that cannot imagine anything as large as a clock. He can only imagine himself.' },
        { kind: 'bg', bg: 'docks', tone: 'cold' },
        { kind: 'narrate', text: 'The north wall runs out into the dry harbour like an arm reaching for something it dropped. Halfway along, at the head of a flight of green-slimed steps that once went down into deep water, a young man stood with his hands held out over the mud.' },
        { kind: 'narrate', text: 'He was perhaps twenty, in a sailor’s coat a little long in the sleeve, with pale hair the wind should have been moving and was not. His palms were turned down, fingers spread, as if warming them at a fire no one else could see. His lips were moving.' },
        { kind: 'narrate', text: 'Below him, the mud shivered. A ripple ran across a puddle the size of a dinner plate — the faintest stir, like a sleeper turning over at the sound of a name — and was still again.' },
        { kind: 'line', who: 'ichabod', text: '…Come on. Come on. You know me. You have known me since I was four years old.' },
        { kind: 'line', who: 'ichabod', text: 'Not the whole sea. Not the flood. A finger’s width. A turn. Only show me you are listening.' },
        { kind: 'line', who: 'ichabod', text: 'Please.' },
        { kind: 'narrate', text: 'Nothing. He lowered his hands and stood a long while looking at the harbour, as you might look at an old friend who has passed you in the street without a flicker.' },
        { kind: 'line', who: 'wren', text: 'Lucien Marée?' },
        { kind: 'line', who: 'ichabod', text: 'You are the Lantern Keeper. My father said you would come. He said it every hour, on the hour. I think he was afraid he would forget he had sent for you.' },
        { kind: 'line', who: 'ichabod', text: 'I am Lucien. I call the tides… I used to.' },
        { kind: 'line', who: 'odile', text: 'You still do. I watched. The water moved for you.' },
        { kind: 'line', who: 'ichabod', text: 'A puddle shivered. When I was small I brought the whole sea in a day early, just to see the herring boats home before supper. Now I can make a puddle shiver, if I stand here long enough to forget my own name.' },
        { kind: 'line', who: 'bastian', text: 'It was a very good shiver, though.' },
        { kind: 'line', who: 'ichabod', text: '…Thank you. No one has ever complimented my shivering before.' },
        { kind: 'narrate', text: 'He almost smiled. It had the stiffness of a door that has not been opened all winter.' },
        { kind: 'line', who: 'wren', text: 'Tell me what happened here.' },
        { kind: 'line', who: 'ichabod', text: 'Nothing happened. That is what happened. The tide went out at midnight, as it was meant to. I was here — I come every New Year’s Eve, for the Lantern Tide. The clock struck, and struck again, and the water simply… stopped at the bottom.' },
        { kind: 'line', who: 'ichabod', text: 'They say on this coast that the sea forgives everything but being kept from the moon. It was a new moon that night — dark, gone under the world. It has stayed dark. I have been pulling on a rope for a year, Keeper, with nobody at the other end.' },
        { kind: 'line', who: 'ichabod', text: 'So the sea waits for a minute that never comes. Water remembers time better than people do. It knows it is owed the turn. It is only too well-mannered to take it.' },
        { kind: 'line', who: 'marigold', text: 'A sea with manners. I have met duchesses with fewer.' },
        { kind: 'line', who: 'odile', text: 'And the lighthouse?' },
        { kind: 'narrate', text: 'Lucien turned to look along the breakwater, and they all looked with him. At the far end the lamp of the Breakwater Light revolved as patiently as ever. Where its beam passed, a long blade of black swept the mud, and the stars in the puddles went out beneath it, one by one, and came back after.' },
        { kind: 'line', who: 'ichabod', text: 'Keeper Brine’s light. He kept it forty-one years. He taught me the tide tables at his kitchen table when I was small — a ruler, a pencil, and a boiled sweet for every right answer. He never let that lamp go out. Not once.' },
        { kind: 'line', who: 'ichabod', text: '…Not once, except one night. He never forgave himself for that night.' },
        { kind: 'line', who: 'wren', text: 'What happened that night?' },
        { kind: 'line', who: 'ichabod', text: 'Ask me further out, Keeper. It is a story that needs more sea under it.' },
        { kind: 'narrate', text: 'Somewhere beyond the bar, deep in the fog, a ship’s bell clanked once — and stopped, as though whoever rang it had remembered there was no longer any point.' },
        { kind: 'line', who: 'ichabod', text: 'There are eleven ships out there. They were coming home for the New Year. They sit on the flat water past the bar with their lights out, and they cannot come in, because there is nothing to come in on. Every night I hear a bell from one of them. Every night it is a little quieter.' },
        { kind: 'line', who: 'bastian', text: 'Are there people on them?' },
        { kind: 'line', who: 'ichabod', text: 'There were.' },
        { kind: 'line', who: 'marigold', text: 'I own a quarter of a schooner, you know. The Annabel Lee. I bought the share in 1911 as a kindness to a captain who could not pay his tailor. No one has ever told me which quarter is mine. I suppose it is out there now, waiting with the rest of her.' },
        { kind: 'narrate', text: 'Corvin opened his satchel. Since the crows had begun flying in from the harbour it had grown heavy with salt: envelopes swollen like loaves left out in the rain, ink run, addresses smeared into small blue clouds. He drew one out and held it to the Lantern so the others could read.' },
        { kind: 'letter', text: 'Dear Hal — they say the boats can’t come in, but I’ve kept your supper warm every night all the same. Three hundred and some suppers now. The dog still sleeps by the door. I haven’t told him. If you see the harbour light, love, don’t trust it. Come home by the stars.', sign: '— your Bet, Ropewalk Row' },
        { kind: 'line', who: 'wren', text: 'Every one of these is addressed to a ship. Not one of them can be delivered. A postman does not like that, Lucien. It sits on his chest at night like a cat that will not be moved.' },
        { kind: 'line', who: 'ichabod', text: 'Then we have the same trouble, you and I. I cannot bring the water in. You cannot carry the letters out. We are two halves of one tide, Keeper — the going and the coming back — and both of us stuck.' },
        { kind: 'line', who: 'wren', text: 'So we do both. The lighthouse first. Whatever has hold of Brine has hold of the tide.' },
        { kind: 'line', who: 'ichabod', text: 'You don’t know what is out there. The harbour is not empty, Keeper — it only looks it. The gulls came back wrong. The night shift at the docks is still working, only the men have no faces now. And there is singing in the fish market. You must not listen to the singing.' },
        { kind: 'line', who: 'odile', text: 'We have walked through worse. We walked through a theatre that had been singing for a year.' },
        { kind: 'line', who: 'ichabod', text: '…The Gloaming? You were there? Then the chandelier — I saw it from this wall, the night it came back on. The whole hill lit up like a cake with all its candles. And I thought, if someone can do that… perhaps.' },
        { kind: 'line', who: 'wren', text: 'Perhaps.' },
        { kind: 'narrate', text: 'Lucien looked at the Lantern then — properly, as people always did the first time, trying to decide whether it was a lamp or a promise. In its light his face was very young and very tired, and, for the first time in a long while, a little curious.' },
        { kind: 'line', who: 'ichabod', text: 'All right. I will take you out. Across the basin, through the market, the crane yard, the customs house, the old pier. Then the breakwater. A mile and a half of mud and stone. In the old days I could have floated you there in a quarter of an hour.' },
        { kind: 'line', who: 'marigold', text: 'In the old days I could have hired a carriage. We are all of us reduced, young man. The trick is to be reduced with style.' },
        { kind: 'line', who: 'bastian', text: 'One, two, three. One, two, three. If I keep counting, the mud won’t notice me.' },
        { kind: 'narrate', text: 'They went down the slimed steps into the bed of the harbour. The mud took their footprints and kept them perfectly — every nail in Corvin’s boots, every small porcelain toe of Columbine’s — as if it had waited a year for something new to remember.' },
        { kind: 'narrate', text: 'There were other footprints already. Small ones, bare, going out towards the wrecks and coming back, out and back, a hundred times over — a tide made of one child. Seraphine saw them, and said nothing, and kept them for later.' },
        { kind: 'narrate', text: 'Behind them, at the root of the north wall, the harbourmaster stood in his doorway with a stub of chalk in his fist and watched them go. When they were small in the fog, he went back to his desk and wrote, beneath all the other words, a new one.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Lantern Keeper. Lantern Keeper. …Don’t forget.' },
        { kind: 'narrate', text: 'Overhead the stars had not moved in a year. Below, the same stars lay in a thousand standing puddles — a sky broken and set out on the ground like crockery after a quarrel. And across all of them, for the first time since midnight, one small light went walking.', tone: 'cold' },
      ],
    },

    // ───────────────────────────────────────────── After 3-1
    {
      id: 'ch3_i1', name: 'Chapter III · The Mudlark', bg: 'docks', tone: 'cold',
      clock: '23:41',
      shots: [
        { kind: 'narrate', text: 'The trawler’s horn came again out of the fog: two short notes and a long one, flat and hoarse, like an old man clearing his throat in an empty church.' },
        { kind: 'narrate', text: 'And from under the wreck of a coal barge that lay keel-up in the mud, somebody small shouted back.' },
        { kind: 'line', who: 'Small voice', text: 'That’s her! That’s the Kittiwake! Two short and a long — that’s for me, that is, he always does it for me!' },
        { kind: 'narrate', text: 'A boy wriggled out from beneath the barge’s rotten hull. Ten years old, perhaps, in an oilcloth coat cut down from a man’s, barefoot, mud to the knees, a sack over one shoulder that clinked when he moved. He saw the Lantern, and stopped dead.' },
        { kind: 'line', who: 'Small voice', text: '…You’re not the Kittiwake.' },
        { kind: 'line', who: 'wren', text: 'No. I’m sorry. I’m the post.' },
        { kind: 'line', who: 'Small voice', text: 'Nobody’s had post down here for a year.' },
        { kind: 'line', who: 'wren', text: 'Then I’m very late, and I apologise. What’s your name?' },
        { kind: 'line', who: 'Tam Hollis', text: 'Tam. Tam Hollis. My dad’s Walter Hollis, skipper of the Kittiwake, out of Vellmoor, registered number VM 41. I say it every morning so it don’t get away from me. You’re standing on my things.' },
        { kind: 'narrate', text: 'They were. All round the barge, laid out on the mud in careful rows like a market stall, were the harbour’s secrets: everything the water had swallowed in a hundred years and given up at the bottom of the ebb.' },
        { kind: 'narrate', text: 'Clay pipes. Buttons off uniforms nobody wore any more. A ship’s bell gone green as a pear. A set of false teeth, grinning at the sky. Wedding rings — dozens, laid out in a ring of their own. And bottles: rows and rows of bottles, stoppered with wax, with paper rolled inside like a held tongue.' },
        { kind: 'narrate', text: 'Whatever the sea had kept, it had altered in the keeping. The iron had gone to lace. The rings wore small green moons of verdigris. The glass was frosted like a breath on a window. Nothing comes back out of the water quite as it went in.' },
        { kind: 'line', who: 'odile', text: 'You have been living out here. Alone. For a year.' },
        { kind: 'line', who: 'Tam Hollis', text: 'Somebody’s got to meet the boat. If I go up into town and he comes in and there’s nobody on the wall, he’ll think I forgot him. You can forget things up there. Down here there’s nothing to do but remember.' },
        { kind: 'line', who: 'bastian', text: 'Are you not cold?' },
        { kind: 'line', who: 'Tam Hollis', text: 'Nobody’s cold any more. Nobody’s hungry neither. Nobody’s anything. Are you a doll?' },
        { kind: 'line', who: 'bastian', text: 'I don’t know. Perhaps. I used to be.' },
        { kind: 'line', who: 'Tam Hollis', text: 'You move better than my sister’s doll, anyway. Hers only does yes and no with its head.' },
        { kind: 'line', who: 'bastian', text: '…Thank you. I think that is the nicest thing anyone has said to me in a year.' },
        { kind: 'line', who: 'wren', text: 'The bottles, Tam. Have you read them?' },
        { kind: 'narrate', text: 'The boy looked at his bare feet for a while. When he spoke again, he spoke to the mud.' },
        { kind: 'line', who: 'Tam Hollis', text: 'Can’t. Never got the hang of it. Dad was going to teach me in the winter, when the boats lay up. I kept them, though. Every one. I thought — somebody wrote them, didn’t they? They wanted somebody to read them. So I kept them for whoever that was.' },
        { kind: 'line', who: 'wren', text: 'That was the right thing to do. It is exactly what I would have done.' },
        { kind: 'narrate', text: 'Corvin sat down on an upturned crate, set the Lantern at his feet, and took the first bottle. The wax broke with a sound like a knuckle. The paper inside was brown as a leaf, the hand old-fashioned and leaning, as if it were walking into a wind.' },
        { kind: 'letter', text: 'To whoever finds this — I am on the brig Constance, three days out, and we are taking on water faster than we can bail. If this reaches Vellmoor, tell Mary Penhallow of Tarry Lane that I am not dead. I am only late. I will always be only late.', sign: '— Jos. Penhallow, 1887' },
        { kind: 'line', who: 'marigold', text: '“Only late.” Forty years of opening nights, and I never once heard a better exit line. Did she get it, I wonder?' },
        { kind: 'line', who: 'wren', text: 'She’s getting it now.' },
        { kind: 'narrate', text: 'The second was a lemonade bottle, the kind with a glass marble in the neck. The paper was lined, torn from a school exercise book, and the letters were large and serious and pressed so hard they stood up on the back of the page like a second, secret letter.' },
        { kind: 'letter', text: 'Dear Sea, please could you give my grandad back. His name is Albert. He has a beard and a blue hat. You can keep the hat. Yours faithfully.', sign: '— Edie Sallow, aged 7' },
        { kind: 'line', who: 'Tam Hollis', text: 'Did it? Give him back?' },
        { kind: 'line', who: 'ichabod', text: 'The sea never gives anyone back, Tam. That isn’t what the sea is for.' },
        { kind: 'line', who: 'ichabod', text: '…But it keeps them. It keeps everything, and it changes what it keeps — iron to lace, gold to little green moons. Look round you. It kept every ring, every button, every letter, and then it gave them to you. That is not nothing.' },
        { kind: 'narrate', text: 'The third bottle was newer than the others. Clear glass, a cork instead of wax, not a single barnacle. It had never been in the sea. It had been thrown — from somewhere high — and had landed in the soft mud without breaking.' },
        { kind: 'narrate', text: 'Corvin unrolled the paper and went very still. Lucien leaned over his shoulder, and his breath caught.' },
        { kind: 'line', who: 'ichabod', text: 'That is his hand. That’s Brine’s. He wrote out every tide table I ever learned in that hand.' },
        { kind: 'letter', text: 'To anyone below. The light is wrong. I made it wrong. Do not come out along the wall. I am not myself for long these days. In the moments I am, I write this, and throw it as far as I can. Keep away from the breakwater. Keep away from me.', sign: '— T. Brine, the Breakwater Light' },
        { kind: 'line', who: 'Tam Hollis', text: 'There’s loads of them. The cork ones. They come down over the wall at night sometimes — plop, plop. I thought it was the gulls being nasty.' },
        { kind: 'line', who: 'odile', text: 'He is still in there. Under whatever the Dimming has made of him, there is a man trying to warn us away from himself.' },
        { kind: 'line', who: 'ichabod', text: 'That is like him. He would rather you hated him than got hurt on his rocks.' },
        { kind: 'narrate', text: 'The horn sounded again out of the fog. Two short, one long. Tam turned towards it the way a sunflower turns, without deciding to.' },
        { kind: 'line', who: 'Tam Hollis', text: 'He saw your light. He must have. He’s not sounded twice in one night since — since ever. You’re going out to the lighthouse, aren’t you? Take me. I can carry things. I know where the mud’s soft.' },
        { kind: 'line', who: 'wren', text: 'Tam. If the Kittiwake comes in tonight, who will be on the wall to meet her?' },
        { kind: 'narrate', text: 'A long pause. The boy’s jaw worked. He was ten years old, and he had been brave for a year, and he was very tired of it.' },
        { kind: 'line', who: 'Tam Hollis', text: '…Me. It’s got to be me.' },
        { kind: 'line', who: 'wren', text: 'Then I have a job for you. I’m appointing you sub-postmaster of the harbour bed. You keep every bottle exactly where it is, safe, until we can find who they belong to. That is a sworn duty. Will you take it?' },
        { kind: 'line', who: 'Tam Hollis', text: 'Do I get a hat?' },
        { kind: 'line', who: 'wren', text: 'When the tide turns, I will personally find you a hat.' },
        { kind: 'narrate', text: 'They left him standing on his upturned crate, chin up, guarding his rows of bottles and rings like a sentry outside a palace nobody else could see. When Columbine looked back, he waved. She waved back, and found she could not stop.' },
        { kind: 'line', who: 'bastian', text: 'Corvin. Is it normal, to want very badly for someone you have only just met to be all right?' },
        { kind: 'line', who: 'wren', text: 'It’s the most normal thing there is. It is the whole of the post, really.' },
        { kind: 'narrate', text: 'Ahead, beyond the dry basin, the roofs of the fish market rose out of the fog — and from somewhere among them, so faint it might have been the wind in a chimney, someone had begun to sing.' },
      ],
    },

    // ───────────────────────────────────────────── After 3-2
    {
      id: 'ch3_i2', name: 'Chapter III · The Dovecote', bg: 'docks', tone: 'cold',
      clock: '00:26',
      shots: [
        { kind: 'narrate', text: 'The last siren came apart like wet paper, and the fish market was quiet. On the slabs lay the catch of the thirty-first of December, 1929 — cod and mackerel and herring bright as new florins, a year dead and not one scale dulled. The Dimming keeps what it takes very nicely.' },
        { kind: 'narrate', text: 'Lucien sat down on an upturned fish box and put his face in his hands. Nobody spoke for a while. The song was still in all of them, the way cold stays in the bones after you have come in from it.' },
        { kind: 'line', who: 'odile', text: 'Lucien. What did it sing to you?' },
        { kind: 'line', who: 'ichabod', text: 'My name. Only my name. In her voice. “Lucien — Lucien, come in off the wall, your supper’s on.” She used to call it from the end of the pier, every night. You could hear it across the whole harbour, over the gulls, over the engines.' },
        { kind: 'line', who: 'wren', text: 'Your mother.' },
        { kind: 'line', who: 'ichabod', text: 'Marguerite Marée. My father has forgotten it, so I say it twice as often. She sailed the Petrel, the pilot boat. She brought the big ships in over the bar. And one night in 1921 she did not come in herself.' },
        { kind: 'line', who: 'ichabod', text: 'She used to say I was her tide and she my moon — wherever she went, I leaned that way. I lean there still. But she went under the world, and a tide cannot follow the moon down there. It can only lie at the bottom, and wait.' },
        { kind: 'line', who: 'bastian', text: 'The siren knew her voice. How could it know her voice?' },
        { kind: 'line', who: 'ichabod', text: 'They are made of the drowned. That is what the old women say. Everyone the sea ever kept and never gave back — the Dimming dredged them up and taught them to sing. I wanted so badly to answer her, Columbine. I nearly did.' },
        { kind: 'line', who: 'bastian', text: 'I know. I had your sleeve. You pulled quite hard.' },
        { kind: 'line', who: 'ichabod', text: '…Thank you for not letting go.' },
        { kind: 'line', who: 'bastian', text: 'Holding on to people is the only thing my hands are good for. Someone cut my strings. I have to use them for something.' },
        { kind: 'narrate', text: 'Then — overhead — a sound none of them had heard in a year. Wings. Not the ragged, salt-crusted shriek of the gull wraiths, but something soft and many, clapping like a congregation: a flock wheeling once round the market roof and settling, white as paper, on the gable opposite.' },
        { kind: 'narrate', text: 'It was a small grey chapel with a lamp in its window — the Mission to Seafarers, according to the board above the door, all its other words long since Dimmed away. On the roof stood a dovecote. And on the ridge beside the dovecote stood a girl.' },
        { kind: 'narrate', text: 'Silver-haired, in a dress of blue and white like the inside of a mussel shell. In one hand she held a gilded birdcage with its little door standing open. Around her wrists and shoulders, loose as scarves, drifted ribbons of water — clear, bright, and moving.' },
        { kind: 'line', who: 'ichabod', text: 'That water is moving. How is that water moving? Nothing in this harbour has moved since midnight.' },
        { kind: 'line', who: 'evangeline', text: 'It’s rain. I caught it in a basin the evening before midnight, while it was still falling. It remembers falling, I think. It hasn’t quite stopped.' },
        { kind: 'line', who: 'evangeline', text: 'You chased the singers out of the market. Thank you. I can hear them from the beds, and so can the men. They don’t sleep well when the singing starts. Will you come in? You look as if you could do with mending, all of you.' },
        { kind: 'bg', bg: 'parlour', tone: 'warm' },
        { kind: 'narrate', text: 'Inside, the mission was one long room of iron beds under a beamed roof, with a stove at one end and a chapel rail at the other. In the beds lay sailors — two dozen men who had come ashore on the thirty-first and never gone home — growing faint against their pillows like pencil sketches being rubbed out.' },
        { kind: 'narrate', text: 'The girl moved among them as if she had done it ten thousand times, which she had. A word here; a hand there; a pillow turned to its cool side. Where her ribbons passed over a sleeping face, its lines came back a little darker, a little more certain, like writing breathed on in frost.' },
        { kind: 'line', who: 'evangeline', text: 'My name is Aveline. Aveline Halcyon. I was given to the mission when I was very small — the chaplain says I came with the cage. I keep the doves, and the beds, and the stove, and the chaplain too, now. He’s the third bed from the end. He forgets the psalms, so I read them to him.' },
        { kind: 'line', who: 'odile', text: 'You have been holding all of these men together alone.' },
        { kind: 'line', who: 'evangeline', text: 'Not alone. I have the doves.' },
        { kind: 'narrate', text: 'She opened a drawer under the chapel rail. Inside, tied in bundles with string, were hundreds of slips of paper, each no bigger than a playing card, each rolled tight enough to fit the ring on a pigeon’s leg.' },
        { kind: 'line', who: 'evangeline', text: 'The ships past the bar. The families wrote to them, and I sent the doves out with the letters, and the doves came back with answers. I read the answers to the men in the beds and the wives on the wall. As long as the letters went to and fro, nobody quite forgot anybody.' },
        { kind: 'line', who: 'wren', text: 'Your doves carry letters to people who can’t come home. My crows bring me letters from people the city has forgotten.' },
        { kind: 'line', who: 'evangeline', text: 'Then between us we’re very nearly a post office. We only want a counter, and a cross little man behind a grille.' },
        { kind: 'line', who: 'marigold', text: 'I volunteer to be the cross little man. I have been rehearsing for years.' },
        { kind: 'narrate', text: 'Aveline laughed — a short, surprised laugh, like a bird startled off a ledge. Then she took a bundle from the very back of the drawer, and the laugh went out of her as though a window had been shut.' },
        { kind: 'line', who: 'evangeline', text: 'Since the autumn the doves have been coming back with blank paper. I send out a letter from a wife, and the dove comes home with nothing on the reply. Not crossed out. Simply empty, like snow nobody has walked on. As if there were no one left on board who remembers how to write.' },
        { kind: 'line', who: 'ichabod', text: 'The bells are getting quieter too. Every night.' },
        { kind: 'line', who: 'evangeline', text: 'I know. I hear them from the roof. I count them, the way you count a sick man’s breaths and pretend you aren’t.' },
        { kind: 'line', who: 'evangeline', text: 'And there’s this. Three weeks ago one of my doves went astray. She didn’t fly out to the ships. She flew to the lighthouse. And when she came back she wasn’t carrying my letter. She had this in her beak.' },
        { kind: 'narrate', text: 'A single page, torn from a ruled book along the stitching, damp at the edges. The hand was the same leaning, careful hand as the bottle in Tam’s mud.' },
        { kind: 'letter', text: 'Nov. 30th. Fog. Wind nil. The gentleman from the city again. Mr. V. He sat in the lamp room an hour, listening to my tide-clock the way a doctor listens to a chest. He asks about the moon as if it owed him money. I did not like him. I liked him less once I understood him.', sign: '— Log of the Breakwater Light' },
        { kind: 'line', who: 'wren', text: '“Mr. V.”' },
        { kind: 'line', who: 'odile', text: 'A tide-clock keeps the time of the water, not the sun. If someone wished to stop the sea, Keeper, that is the door they would knock on.' },
        { kind: 'line', who: 'bastian', text: 'V. …I have letters on me too. Little brass ones. Only they aren’t a V. They’re an A and a V.' },
        { kind: 'narrate', text: 'Nobody answered that. Columbine looked at her own wrist for a long time, where the signature sat under the red silk like a bruise, and then drew her sleeve down over it.' },
        { kind: 'line', who: 'evangeline', text: 'You’re going out to the lighthouse.' },
        { kind: 'line', who: 'wren', text: 'We are.' },
        { kind: 'line', who: 'evangeline', text: 'Then I’m coming. No — please don’t say it. I know I’ve never set foot past the end of the harbour wall. I know what the cage looks like. Everyone always looks at the cage.' },
        { kind: 'line', who: 'evangeline', text: 'It isn’t to keep anything in. It never was. A dove doesn’t come home to a field — she comes home to a door she knows. The cage is the door. I have kept it open twenty years, so that everything I sent out would have somewhere to come back to.' },
        { kind: 'line', who: 'evangeline', text: 'If my doves can’t reach the ships, then I shall walk out and ask the lighthouse myself why not. And I’ll leave the door open behind me.' },
        { kind: 'line', who: 'odile', text: 'I have wings, and I have spent a year standing still under a sky that will not move. You have a cage, and you have spent a year flying letters across a sea that will not move. I think we will understand each other very well.' },
        { kind: 'narrate', text: 'Aveline went down the row of beds one last time. She read the third bed from the end a psalm, all the way through, and the old chaplain’s lips moved with hers on the last line. Then she set her ribbons drifting slow above the beds like a canopy, and told them to keep everyone till she came back.' },
        { kind: 'narrate', text: 'On the roof the doves rose all at once and circled the chapel three times. When the troupe set out across the mud towards the crane yard, the flock went with them overhead, white against the frozen stars, like a sentence nobody had yet finished writing.', bg: 'docks', tone: 'cold' },
      ],
    },

    // ───────────────────────────────────────────── After 3-4
    {
      id: 'ch3_i3', name: 'Chapter III · Undelivered', bg: 'docks', tone: 'warm',
      clock: '01:52',
      shots: [
        { kind: 'narrate', text: 'The customs house was full of green light. Four thousand jars of fireflies had burst their seals at once, and the long hall — its high counters, its pigeonholes, its racks of rubber stamps — glowed like the bottom of a pond on a summer evening, when the weed is lit from above.' },
        { kind: 'narrate', text: 'At the far counter a clerk in sleeve-garters was still at work. Stamp. Blot. Stamp. Blot. His stamp had run dry some time last January. He had not noticed. Each sheet he laid on the pile was a little blanker than the last, and so was he.' },
        { kind: 'narrate', text: 'Then a firefly landed on the back of his hand, and blinked. He stopped with the stamp in the air and looked at the insect for a long moment, as if it had asked him a difficult question.' },
        { kind: 'line', who: 'Customs Clerk', text: '…Duty’s not been paid on those.' },
        { kind: 'line', who: 'wren', text: 'Put it on the Lantern’s account.' },
        { kind: 'line', who: 'Customs Clerk', text: 'The Lantern hasn’t got an account.' },
        { kind: 'line', who: 'wren', text: 'Then open one. I’m good for it.' },
        { kind: 'narrate', text: 'The clerk blinked, very much as the firefly had. Something came back into his face — a little colour, a little irritation, which is how most clerks begin.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'Pettigrew. Ezra Pettigrew, Second Clerk of Customs and Excise, Vellmoor Port. My mother called me Ezzie. Nobody else was ever allowed to. Good heavens. What day is it?' },
        { kind: 'line', who: 'odile', text: 'It is still the thirty-first of December, Mr. Pettigrew. It has been for some time.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'That can’t be right. I’d have been paid.' },
        { kind: 'narrate', text: 'He found the ledger without needing to look. Thirty years of habit carried his hand to the right shelf, the right volume, the right page. He turned it towards them under the green light with the solemnity of a curate turning the great Bible on its brass eagle.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'Consignment four-four-one. Lampyridae, live, four thousand jars. Shipped from the southern marsh-country on the Grace Darling, landed the twenty-ninth. Duty paid in full, in gold sovereigns, cash. Held in bond at the purchaser’s particular request.' },
        { kind: 'line', who: 'ichabod', text: 'Four thousand jars. That’s the whole season. Every firefly the marsh-country caught last summer — every June night of it, in a jar.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'Every last one. Prices went through the roof. The lamp-festivals in three towns had to make do with candles, I’m told. The gentleman did not haggle. I had the feeling he would have paid anything at all.' },
        { kind: 'line', who: 'wren', text: 'The purchaser. Read us the name.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'A. Vire, Master Clockmaker, Spindle Street. For delivery to Miss C. Vire, the sickroom, number nine. Then underneath, in his hand, underlined twice: “Deliver at first light, 1st January 1930. Not before. On no account before.”' },
        { kind: 'narrate', text: 'The hall was very quiet. The fireflies blinked on and off among the pigeonholes like a slow thought that nobody was yet ready to finish.' },
        { kind: 'line', who: 'marigold', text: 'He bought a whole summer of light, and asked for it to be kept until morning.' },
        { kind: 'line', who: 'ichabod', text: 'And then made sure there wasn’t one.' },
        { kind: 'line', who: 'odile', text: 'We do not know that yet, Lucien. We only know what he bought.' },
        { kind: 'line', who: 'ichabod', text: 'We know his name was on a log page in the lighthouse. We know he sat by Brine’s tide-clock asking about the moon. And now we know he wanted all the light in the world shut in a box until the first of January. What more is there to know?' },
        { kind: 'line', who: 'odile', text: 'Why.' },
        { kind: 'narrate', text: 'Corvin had gone to the first of the broken crates. Wedged between the straw and the slats was a small square envelope, cream-coloured, unaddressed, the flap merely tucked in. It had not been meant for the post. It had been meant for a pair of small hands, at first light.' },
        { kind: 'letter', text: 'For my little star, who asked me if the stars could come down and visit her, since she is not allowed to go out and see them. They could not. These could. Leave the lid off and they will stay as long as you like. Happy New Year, my darling.', sign: '— Papa' },
        { kind: 'narrate', text: 'Corvin read it twice. Then he folded the card back into its envelope as though it were still warm, and put it not among the others but in the satchel’s inner pocket — beside the one letter he had never opened. Two undelivered letters, lying face to face.' },
        { kind: 'line', who: 'wren', text: 'This was never delivered.' },
        { kind: 'line', who: 'marigold', text: 'Corvin—' },
        { kind: 'line', who: 'wren', text: 'Number Nine, Spindle Street. First light. I have carried letters for eleven years, Count. I have delivered them in snow and in floods and once, in 1926, to a man up a tree. I do not leave a letter in the sorting office because the morning is late.' },
        { kind: 'line', who: 'wren', text: 'I will deliver it. I don’t know when. But I will deliver it.' },
        { kind: 'narrate', text: 'Behind them, Columbine had not moved from the counter. She was looking at the ledger — not at the words but at the signature. A. Vire. The A was tall and narrow, crossed twice, like a little ladder. The V had a small hooked tail, as though it had snagged on something going by.' },
        { kind: 'narrate', text: 'Slowly, she drew back her sleeve. On the porcelain inside her wrist, in tiny inlaid brass, was the same A. The same two crossbars. The same V, with the same small hooked tail.' },
        { kind: 'line', who: 'bastian', text: 'It’s on my wrist. And my knee. And behind my ear, where nobody is meant to look. I always thought it was a sort of… maker’s mark. Like on the bottom of a teacup.' },
        { kind: 'line', who: 'bastian', text: 'It is the same hand. Isn’t it? The same hand wrote this, and made me.' },
        { kind: 'line', who: 'evangeline', text: 'Columbine—' },
        { kind: 'line', who: 'bastian', text: 'Was I a present too? Was I meant to be delivered somewhere, at first light, and nobody came to collect me?' },
        { kind: 'narrate', text: 'Corvin came and stood beside her. He did not touch her wrist, or pull the sleeve down, or tell her not to look. He only stood there, the way you stand beside someone at a graveside, so they know which side of them is not alone.' },
        { kind: 'line', who: 'wren', text: 'You weren’t delivered, Columbine. You arrived. It isn’t the same thing at all.' },
        { kind: 'line', who: 'bastian', text: 'What’s the difference?' },
        { kind: 'line', who: 'wren', text: 'A parcel goes where it’s addressed. You walked out of a shop window with your strings cut and came to find us. Nobody addressed you to Corvid Lane. You chose it.' },
        { kind: 'narrate', text: 'Columbine said nothing. But she let a firefly settle on the back of her hand, over the brass letters, and watched it blink there, green and gold, as if it were reading them.' },
        { kind: 'line', who: 'marigold', text: 'I knew him, you know. Vire. Not well. Nobody knew him well. He built the clock above the proscenium at the Gloaming — I commissioned it in 1919. He would not take my money until it had kept time to the second for a full month.' },
        { kind: 'line', who: 'marigold', text: 'He came to the Christmas pantomime one year. Third box from the left. He had a little girl with him in a velvet frock, and she fell asleep in the second act with her head on his arm.' },
        { kind: 'line', who: 'marigold', text: 'He sat through the whole of the third act without moving that arm. I remember thinking: there is a man who would let his arm fall off sooner than wake her.' },
        { kind: 'line', who: 'odile', text: 'What did he say, when you commissioned the clock?' },
        { kind: 'line', who: 'marigold', text: 'I asked him why he made clocks, of all things. He said: “So that people are never late for what they love.” I thought it a charming answer at the time. I find, tonight, that I like it rather less.' },
        { kind: 'narrate', text: 'Mr. Pettigrew had been listening with the rubber stamp still in his fist. He set it down on the counter, gently, as if laying down a weapon.' },
        { kind: 'line', who: 'Ezra Pettigrew', text: 'He asked me something, when he paid. Whether the fireflies would last a long night. A very long night, he said. I told him they’re hardy little things, sir. They’ll keep as long as anyone likes. So long as someone remembers to take the lid off.' },
        { kind: 'narrate', text: 'Through the tall windows the freed fireflies were drifting out across the harbour bed in a long, slow, glimmering river — west, towards the old pier, where something under the planks had begun, very faintly, to glow back.', tone: 'warm' },
      ],
    },

    // ───────────────────────────────────────────── After 3-5
    {
      id: 'ch3_i4', name: 'Chapter III · The Lantern Tide', bg: 'docks', tone: 'cold',
      clock: '02:37',
      shots: [
        { kind: 'narrate', text: 'Beneath the sunken pier, the drowned lanterns were opening their eyes.' },
        { kind: 'narrate', text: 'There were thousands of them: paper lanterns, oiled and pleated, each the size of a loaf, lying in the mud between the pilings in drifts like fallen leaves. As the fireflies settled on them, one by one, the old candle-stubs inside caught again — not with fire, but with something paler. A memory of fire.' },
        { kind: 'line', who: 'bastian', text: 'They have writing on them. Every single one.' },
        { kind: 'line', who: 'ichabod', text: 'Names. It’s the Lantern Tide. Every New Year’s Eve the families of everyone the sea has kept write the names on lanterns and set them on the ebb at midnight. The tide carries them out over the bar. One light for every name. The sea takes them, and remembers.' },
        { kind: 'line', who: 'ichabod', text: 'Only last year the tide stopped at the bottom, and the lanterns stopped with it. They drifted in under the pier and settled in the mud. Every name in Vellmoor that anyone ever wept over. Just… lying here. Unread. Like letters with nobody to carry them.' },
        { kind: 'narrate', text: 'They went in among the pilings, stooping under the dripping crossbeams. Corvin held the Lantern low. Names came up out of the dark at them as they passed, one after another, in a hundred different hands.' },
        { kind: 'narrate', text: 'JOHN TREGARRON, THE BOUNTIFUL, 1898. HARRY AND WILL SKEWES, BROTHERS, 1911. “DAD — COME HOME BY THE STARS.” MARTHA, WHO SWAM OUT AFTER THE DOG. GRANDAD ALBERT. NO NAME, ONLY: “THE BOY FROM THE GOOD HOPE, WHOM NOBODY CLAIMED. WE CLAIM HIM.”' },
        { kind: 'line', who: 'bastian', text: 'Grandad Albert. That’s Edie’s grandad, from Tam’s bottle. The one with the blue hat.' },
        { kind: 'line', who: 'wren', text: 'Then someone came down to the wall for him, too.' },
        { kind: 'line', who: 'evangeline', text: 'I wrote some of these. For the men who died in the mission beds with nobody to write for them. I didn’t know where else to put their names.' },
        { kind: 'line', who: 'odile', text: 'You put them in exactly the right place.' },
        { kind: 'narrate', text: 'Lucien had gone on ahead. He knew where he was going. He went down on his knees in the mud beside the eleventh piling from the end, lifted a lantern out of the drift, and held it the way you would hold a bird with a broken wing.' },
        { kind: 'narrate', text: 'The paper was newer than most. The letters were careful and upright, the hand of a young man who had learned to write from tide tables. MARGUERITE MARÉE — THE PETREL — 1921. And beneath, smaller: Come in by the stars, Maman. I am on the wall.' },
        { kind: 'line', who: 'ichabod', text: 'I write one every year. Nine of them now. This was the ninth. It was meant to be out past the bar by a quarter past twelve, keeping her company.' },
        { kind: 'line', who: 'ichabod', text: '“Tell the ones the sea has kept we know just where they are.” That’s what we sing. And all year she has been lying under a pier a mile from her own front door, in the dark, and I never came.' },
        { kind: 'line', who: 'wren', text: 'Lucien. The night the Breakwater Light went out.' },
        { kind: 'line', who: 'ichabod', text: 'Yes. You wanted the story with more sea under it. Well. This is as much sea as there is.' },
        { kind: 'line', who: 'ichabod', text: 'March, 1921. I was twelve. There was a liner due — the Orsova, three funnels and a band on deck. I wanted to see her come in before bedtime. So I went to the end of the north wall, and I called the tide in early. An hour early. Just to see.' },
        { kind: 'line', who: 'ichabod', text: 'The Petrel had to go out on it, to bring the Orsova over the bar. My mother went. There was fog coming in off the sea, thick as fleece. And that night — the one night in forty-one years — the Breakwater Light went dark.' },
        { kind: 'line', who: 'ichabod', text: 'The Orsova came in safe on the Petrel’s lamp. The Petrel went on the rocks below the breakwater at twenty to three. They found the tiller in the morning. That was all the sea gave back. A tiller. Her hand had been on it.' },
        { kind: 'line', who: 'bastian', text: 'Lucien…' },
        { kind: 'line', who: 'ichabod', text: 'I called the tide in, Columbine. I did. The tide that took her out. And now the sea won’t move for me any more, and I keep thinking — well. It took its time. But it was always going to send me the bill.' },
        { kind: 'narrate', text: 'A footstep on the planks above. Then a second, heavier, uncertain — the step of a big man who is not sure the floor will hold him. Green light spilled down between the boards. Someone had followed the fireflies.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Lucien? Lucien, is that — I saw the light from the office. I couldn’t think what it was. I couldn’t think what night it was. Then I thought: the lanterns. It’s the lanterns, isn’t it.' },
        { kind: 'narrate', text: 'He came down the pier ladder rung by rung, his chalk-scrawled hands white on the iron. He crossed the mud to his son and looked down at the lantern in Lucien’s arms. His lips moved over the letters. Nothing came.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'I can’t read it. It’s her, isn’t it. It’s her name and I can’t — the letters are there and they won’t go into words. They slide. Lucien, what was her name? I am so sorry. What was her name?' },
        { kind: 'line', who: 'ichabod', text: 'Marguerite.' },
        { kind: 'narrate', text: 'The big man swayed as if a wave had struck him, though there had been no waves for a year. Then he sat down in the mud — simply sat, the way a child sits — and laid his hand flat on the lantern.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Marguerite. Margot. She hated Marguerite. Said it made her sound like a bishop’s aunt. Margot. Margot Marée, who could thread a pilot boat through the eye of a needle in a gale and couldn’t boil an egg. Oh — oh, there she is. There she is.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'Son. Is that what you’ve been thinking? All these years, on the wall? That you called the sea and it took her?' },
        { kind: 'line', who: 'ichabod', text: 'I did call it.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'You were twelve. You brought the water in an hour early because you wanted to see a ship with three funnels. Your mother went out on it because a ship needed her, and she always went. She’d have gone on a tide from the moon itself. That was her, not you.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'And the sea hasn’t stopped to punish you, boy. I’ve been harbourmaster forty years. The sea does not know your name well enough to hold a grudge. The sea has stopped because somebody stopped it.' },
        { kind: 'narrate', text: 'Lucien did not answer. But he leaned, very slightly, into his father’s shoulder, the way a moored boat leans against the quay when the water drops — and stayed there.' },
        { kind: 'narrate', text: 'Corvin lifted the Lantern. He touched its glass, very gently, to the pleated paper of Margot Marée’s lantern, and the stub of candle inside caught with a small, real, yellow flame.' },
        { kind: 'narrate', text: 'Then the flame leapt. Lantern to lantern along the mud, like a rumour through a crowd — to John Tregarron, to the Skewes brothers, to Martha who swam out after the dog, to the boy from the Good Hope whom nobody claimed. In a breath the whole underside of the pier was a field of names, burning.', tone: 'warm' },
        { kind: 'line', who: 'evangeline', text: 'Oh. Oh, look at them.' },
        { kind: 'line', who: 'odile', text: 'Read them. All of you. Aloud. Any of them. It doesn’t matter which.' },
        { kind: 'narrate', text: 'So they did. Seraphine read in a clear, low voice, as if reading a horoscope she believed. Valerian read like an actor at a memorial; his voice broke twice, and he did not apologise. Aveline read the names she had written herself. Columbine read slowly, sounding out the hard ones.' },
        { kind: 'narrate', text: 'And beneath their voices — so faint that afterwards none of them could swear to it — the mud between the pilings made a sound. A long, soft, sucking sigh. As though something enormous, a long way off, had remembered for a moment that it used to breathe.' },
        { kind: 'line', who: 'ichabod', text: '…Did you hear that? Keeper, did you hear that?' },
        { kind: 'line', who: 'wren', text: 'I heard it.' },
        { kind: 'line', who: 'ichabod', text: 'That was the sea. That was the sea, listening.' },
        { kind: 'narrate', text: 'The harbourmaster got up out of the mud with his son’s help. At the foot of the ladder he stopped, licked his thumb, rubbed the chalk off the back of his hand — Lucien, Lucien, Lucien — and wrote there instead, very slowly, in large letters: MARGOT.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'I’ll keep the lamp in the office window. If the boats come in, they’ll want a light that isn’t lying to them. Go on, the lot of you. Go and give that old fool on the breakwater a piece of my mind.' },
        { kind: 'line', who: 'Harbourmaster Marée', text: 'And Lucien — when you see him. Brine. Tell him… tell him Margot never once in her life blamed a lighthouse for the weather.' },
        { kind: 'narrate', text: 'Above the pier the fog had thinned enough to show the breakwater again: a long black arm of stone, and at the end of it the lighthouse, turning, turning, pouring its darkness out over a sea that had, for one breath, stirred.', tone: 'cold' },
      ],
    },

    // ───────────────────────────────────────────── After 3-6
    {
      id: 'ch3_i5', name: 'Chapter III · The Keeper’s Rounds', bg: 'docks', tone: 'cold',
      clock: '04:20',
      shots: [
        { kind: 'narrate', text: 'At the root of the breakwater, where the stone arm left the land, stood the keeper’s net-loft: a tarred wooden shed on stilts with a crooked chimney, so weathered it looked less built than grown, like a barnacle that had made something of itself.' },
        { kind: 'narrate', text: 'They went in out of the fog to rest before the last mile. There was a stove, and someone found coal. There was a kettle, and someone found tea, a year old and none the worse. There was one chair by the window — and none of them, without anyone saying so, would sit in it.' },
        { kind: 'narrate', text: 'It was his chair. The shape of him was still in the cushion. Beside it on the sill stood a tobacco tin of boiled sweets, a pencil worn to a stub, and a tide table for 1930, filled in by hand, every day of the year. Every high water. Every low. All the way to December.' },
        { kind: 'line', who: 'ichabod', text: 'He always did the next year’s table at Christmas. He said it was a kind of prayer. If you write down the tides for a whole year, you are promising the sea you expect it to keep its appointments.' },
        { kind: 'line', who: 'odile', text: 'And it hasn’t kept a single one.' },
        { kind: 'line', who: 'ichabod', text: 'No. But look — he did the whole year anyway. He must have known by then. And he still did it.' },
        { kind: 'narrate', text: 'Lucien took a boiled sweet from the tin, turned it over in his fingers, and put it back. On the wall above the stove, pinned to the planking with fish-hooks, hung a dozen loose pages in the same leaning hand — torn from a logbook and nailed up where a man would see them every day.' },
        { kind: 'line', who: 'wren', text: 'He tore them out of the log. Why would a keeper tear pages out of his own log?' },
        { kind: 'line', who: 'evangeline', text: 'So he couldn’t close the book on them.' },
        { kind: 'letter', text: 'March 14th, 1921. Fog thick from the south-west. Nan very poorly. I sat with her past the hour. Lamp ran dry 2:10 am. Petrel struck below the wall 2:40 am. Mrs Marée lost. God keep her. God keep the boy. I will not sleep again.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'May 2nd, 1921. Nan buried Tuesday. Counted ships in: 9. Counted ships out: 9. Lamp trimmed, wick cut, oil full. Did not sleep. I find I do not need to. A keeper who sleeps kills people.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'Aug. 19th, 1923. The Marée boy on the wall again, calling the water. He doesn’t look at the light. I don’t blame him. I left a tide table and a sweet on the steps for him. In the morning both were gone. That is something.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'June 21st, 1925. Longest day. Lit 9:41 pm, forty-nine seconds after sunset, as always. Marée boy on the wall. Taller. Left the table and a sweet. Gulls had the sweet. Will leave two.', sign: '— Log of the Breakwater Light' },
        { kind: 'line', who: 'ichabod', text: 'That was him? I thought — I always thought it was my father who left them. Every week, for years. A table and a sweet, on the bottom step.' },
        { kind: 'line', who: 'ichabod', text: 'He couldn’t say it to my face. So he taught me the whole sea instead, one week at a time, on the bottom step of the north wall.' },
        { kind: 'narrate', text: 'There were more pages. The years went by in them — ships counted in and counted out, oil and wick, wind and fog — and in all of them not one night of sleep. Then the hand began to change. It grew smaller, and harder, and pressed so deep the pencil had torn the paper.' },
        { kind: 'letter', text: 'Nov. 3rd, 1929. A gentleman from the city, to see the tide-clock in the lamp room. Mr. V. A clockmaker, he says, and I believe it. Very polite. Very tired. He asked how often ships are lost on this coast. I told him. He wrote it down.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'Dec. 12th, 1929. Mr. V. again. He asked me what I would give for one night when no ship sailed, and so none could sink. I told him to get out of my light. He went. He left his card on the chart table. I have not thrown it away.', sign: '— Log of the Breakwater Light' },
        { kind: 'narrate', text: 'Under the last page, pinned through by the same fish-hook, was a small white card with an engraved border. A. VIRE. MASTER CLOCKMAKER. GEARWRIGHT ROW. On the back, in a different, finer hand: “The offer stands until midnight on the 31st. I would not ask if there were any other way.”' },
        { kind: 'line', who: 'marigold', text: 'He knew exactly which door to knock on. Not the brave, and not the wicked. The grieving. The grieving will sign anything, if you promise them that nobody else will ever have to feel what they feel.' },
        { kind: 'line', who: 'marigold', text: 'I have watched it from the box office for forty years, you know. Love makes the most dreadful bargains. I very nearly made one or two myself.' },
        { kind: 'line', who: 'evangeline', text: 'There’s something in the coat.' },
        { kind: 'narrate', text: 'On a peg by the door hung a keeper’s oilskin, stiff with salt. In its inside pocket, worn soft as cloth from years against a man’s chest, was a letter. Not to anyone in particular. Not in the keeper’s hand. A woman’s writing, unsteady, as if written in bed.' },
        { kind: 'letter', text: 'Toby — don’t you sit with me tonight. The fog’s coming in, and the Petrel’s out, and Margot’s boy has called the water early again, the little devil. I’ll keep till morning. Go up to your light, love. I’ll be here when you come down.', sign: '— Nan' },
        { kind: 'narrate', text: 'Nobody said anything for a long time. The stove ticked. Outside, the beam of the lighthouse went over the roof of the loft, and for a moment the window turned black, and then came back.' },
        { kind: 'line', who: 'bastian', text: 'He didn’t go up.' },
        { kind: 'line', who: 'wren', text: 'No. He stayed with her.' },
        { kind: 'line', who: 'bastian', text: 'Then he was choosing between two people he loved, and whichever he chose, someone was going to be in the dark. That isn’t wickedness. That’s just… arithmetic. Horrible arithmetic.' },
        { kind: 'line', who: 'odile', text: 'And he has done the sum again every night for nine years. That is what the Dimming found in him. Not cruelty. A man who would rather nothing ever sailed again than lose one more boat to his own two hands.' },
        { kind: 'narrate', text: 'Later, while the others slept or pretended to, Columbine sat on the step of the loft beside Aveline, watching the beam go round. The water ribbons lay in Aveline’s lap like a sleeping cat, rising and falling.' },
        { kind: 'line', who: 'bastian', text: 'May I ask you something? Your cage has an open door. My strings are cut. Which of us do you think is freer?' },
        { kind: 'line', who: 'evangeline', text: 'I’ve thought about that all year, on the roof. I think — whichever of us decides to walk somewhere first. Freedom isn’t the open door, or the scissors. It’s the first step after.' },
        { kind: 'line', who: 'bastian', text: 'Then I think we are both quite free tonight. We are walking out along a breakwater to a lighthouse that shines darkness. Nobody would ever tell a doll or a dove to do that.' },
        { kind: 'line', who: 'evangeline', text: 'No. They’d tell us to stay on the shelf and in the cage. I’m very glad nobody was listening.' },
        { kind: 'narrate', text: 'Seraphine had not slept. She stood in the doorway with her wings folded close, looking up at the motionless sky. Corvin came and stood beside her, the Lantern turned low.' },
        { kind: 'line', who: 'wren', text: 'You’ve been looking at Brine’s chair all night.' },
        { kind: 'line', who: 'odile', text: 'Have I? …Yes. I suppose I have.' },
        { kind: 'line', who: 'wren', text: 'The future you won’t speak of. “The morning comes. Not for everyone.” Is he in it?' },
        { kind: 'line', who: 'odile', text: 'Do not ask me that, Corvin. Not tonight. Not with him at the end of the wall, and Lucien asleep by his stove.' },
        { kind: 'line', who: 'odile', text: 'I will tell you only this. Everything I have read in the sky since midnight has been about holding on. Tonight, for the first time, I keep seeing the other thing. Letting go. It is a very hard star to look at.' },
        { kind: 'narrate', text: 'Corvin did not press her. His hand went to the satchel’s inner pocket, where two unopened letters lay face to face — a child’s careful envelope addressed to whoever stops the clock, and a father’s card addressed to no one, written for first light.' },
        { kind: 'narrate', text: 'Before they left, Lucien went back to the window. He took the stub of pencil from the sill, opened Brine’s tide table for 1930 at the first of January, and under HIGH WATER, beside the keeper’s neat figures, wrote in his own upright hand: Please.' },
        { kind: 'line', who: 'ichabod', text: 'Come on, then. It’s a mile of stone, and he’s at the end of it. He taught me never to keep the tide waiting. I don’t suppose he meant it like this.' },
        { kind: 'narrate', text: 'They went out onto the breakwater. Behind them the loft door swung shut, and the empty chair by the window sat facing the sea, as it had every night for forty-one years, waiting for someone to come down from the light.', tone: 'cold' },
      ],
    },

    // ───────────────────────────────────────────── Ending
    {
      id: 'ch3_end', name: 'Chapter III · The Last Log', bg: 'docks', tone: 'cold',
      clock: '05:55',
      shots: [
        { kind: 'narrate', text: 'The black beam stuttered. Once, twice — like a heart missing its step — and the great lens at the top of the lighthouse ground to a halt, half turned, its dark face to the sea.' },
        { kind: 'narrate', text: 'The thing that had been Keeper Brine let go of the rail. The fog it had worn for a year came off it in long grey rags, the way wet sailcloth comes off a mast, and blew out through the broken glass of the lamp room. What was left knelt on the iron floor. An old man. Only an old man.' },
        { kind: 'narrate', text: 'He had a beard like a frost and a jersey darned at both elbows. His eyes were milky with fog. He looked round the lamp room as if waking in a stranger’s house, and his gaze went slowly from face to face until it came to Lucien’s, and stopped.' },
        { kind: 'line', who: 'Tobias Brine', text: '…Marée’s boy?' },
        { kind: 'line', who: 'ichabod', text: 'Yes, keeper. It’s Lucien.' },
        { kind: 'line', who: 'Tobias Brine', text: 'You’ve grown. You’ve gone and grown. How long?' },
        { kind: 'line', who: 'ichabod', text: 'A year, keeper. A year since midnight. And nine before that.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Nine years. And not a word between us the whole of it, but tide tables and sweets on a step. I am an old coward, Lucien. I could keep a light in a gale, but I could never once look you in the eye.' },
        { kind: 'line', who: 'ichabod', text: 'I know about the step. I know it was you. I found the pages in the loft.' },
        { kind: 'narrate', text: 'The old man shut his eyes. His hand moved on the iron floor, feeling for something, the way a blind man feels for a familiar banister.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Your mother. The Petrel. I let the lamp run dry. I sat with Nan, and I let it run dry, and your mother came in on the dark and the rocks had her. I have trimmed this wick ten thousand nights since. It doesn’t bring the one night back. Nothing does.' },
        { kind: 'line', who: 'ichabod', text: 'Keeper. My father sends a message. He says — Margot never once in her life blamed a lighthouse for the weather.' },
        { kind: 'narrate', text: 'Something went out of the old man’s shoulders then. Not the life — not yet. Something heavier, that he had carried up and down a hundred and forty iron stairs every night for nine years. He set it down on the floor of the lamp room and did not pick it up again.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Margot. …Yes. Yes, that’s her all over. She’d have said it with her hands on her hips.' },
        { kind: 'line', who: 'ichabod', text: 'And I don’t either. Blame you. I thought I did. I thought I had to blame somebody, and it was always either you or me. It was the fog. It was only ever the fog.' },
        { kind: 'line', who: 'wren', text: 'Mr. Brine. The tide. What did he ask you for?' },
        { kind: 'line', who: 'Tobias Brine', text: 'Read the log. It’s all in the log. I could never say it out loud — not to the sea, not to God. I wrote it down, so it would be somewhere outside of me. The rest I’ve been throwing over the wall in bottles for a year.' },
        { kind: 'line', who: 'Tobias Brine', text: 'And the clock — there. The tide-clock. He fitted it himself, with his own hands, two days after Christmas. It’s his clock that holds the sea. Not mine. Mine was only ever the light.' },
        { kind: 'narrate', text: 'He tried to stand, and could not. Aveline was at his side before anyone saw her move, her water ribbons wrapping his hands. For a moment the colour came back into his face. Then it went out again, slowly, gently, like a lamp being turned down rather than snuffed.' },
        { kind: 'line', who: 'evangeline', text: 'I can’t hold him. Corvin, I’m sorry — there’s nothing left for the water to hold on to. He’s been gone a long while. He was only waiting.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Don’t you fret, little dove. You’ve held enough. I know you — you’re the mission girl. Your birds came to my window every morning. I used to save them crusts.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Lucien. When the water comes. Count them in for me. Every one. Count them in and write it down. A ship isn’t home till it’s written.' },
        { kind: 'line', who: 'ichabod', text: 'I will. Every one.' },
        { kind: 'line', who: 'Tobias Brine', text: 'And turn my light round, lad. It’s been facing the wrong way long enough. Nan will be wondering where I’ve got to.' },
        { kind: 'line', who: 'Tobias Brine', text: 'Wind nil. Fog lifting. Keeper… going below.' },
        { kind: 'narrate', text: 'He did not so much die as go out with the turning of a page. One moment there was an old man on the floor of the lamp room, smiling a little at nothing. The next there was a darned jersey, a pair of boots, and a fine dust of salt that glittered once in the Lantern’s light. Salt, and the memory of salt.' },
        { kind: 'narrate', text: 'Seraphine stood a long time with her eyes closed. When she opened them she did not look at the sky. She looked at Lucien, and went and stood beside him, and said nothing at all, which was the kindest thing she knew how to say.' },
        { kind: 'narrate', text: 'Keeper Brine’s logbook lay on the chart table where he had left it. It was the one thing in the lighthouse the Dimming had not swallowed. Its final entry is dated the thirty-first of December, 1929. 11:59 pm.' },
        { kind: 'narrate', text: 'Corvin did not read it at once. He turned back first, as he always did with letters, to what came before — because the last page of anything only makes sense if you know what it cost to get there.' },
        { kind: 'letter', text: 'Dec. 24th, 1929. Mr. V. again, and this time I let him in. He brought no tobacco and no card. He sat in Nan’s chair and he wept, and I did not know where to put myself. He has a little girl. She is poorly. The doctors give her days.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'Dec. 27th, 1929. Mr. V. fitted a new mechanism to my tide-clock. He says it will hold the water at the bottom of the ebb, if I keep the light turned inward at the hour. Nothing will sail. Nothing will sink. I said I would think on it. God help me, I am thinking on it.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'Dec. 31st, 1929. 11:40 pm. Fog. Eleven ships due in for New Year. The Kittiwake. The Annabel Lee. Others. The lanterns are on the north wall. I can see the Marée boy among them. If I say yes, they will not come in. If I say yes, they will not be lost.', sign: '— Log of the Breakwater Light' },
        { kind: 'letter', text: 'Mr. Vire came again tonight. He asked me to hold the tide at midnight. His daughter Colette is sick, and the doctor says she will not see the morning. He means to make sure there isn’t one. God forgive me, I said yes.', sign: '— Log of the Breakwater Light' },
        { kind: 'narrate', text: 'Tucked into the binding behind the last page was a photograph: a man in a dark coat on this same breakwater, on a summer’s day, holding a small girl by the hand. The salt had eaten at the print — her face was lost in a white bloom — but her frock was dark and full-skirted, and there was a ribbon in her hair.' },
        { kind: 'narrate', text: 'On the back, in a hand they all knew now, with its tall crossed A and its hooked V: “C. on the wall, July. She wanted to see where the ships come home.”' },
        { kind: 'line', who: 'bastian', text: 'Colette… “Dance until morning, Colette.” That was the voice. That is what he said to me.' },
        { kind: 'line', who: 'bastian', text: 'Only he wasn’t saying it to me. Was he. He was saying it past me, to someone else. And I kept the words, because they were the only words I had, and I thought they were mine.' },
        { kind: 'narrate', text: 'She held out her hand for the photograph, and Corvin gave it to her. She looked at it a long time — longer than anyone looks at a stranger. Then she slid it into her sleeve, over the brass letters on her wrist, and did not show it to anyone again.' },
        { kind: 'line', who: 'ichabod', text: 'Vire. Aldous Vire, the clockmaker. He built every clock in this city. The Cathedral Clock was his masterpiece.' },
        { kind: 'line', who: 'wren', text: 'And he stopped it. To keep his daughter alive.' },
        { kind: 'line', who: 'odile', text: 'Not alive. Unfinished. A night that never ends is not a life — it is a held breath.' },
        { kind: 'line', who: 'marigold', text: 'He bought every firefly in the south. He bought the keeper’s grief, and the harbour’s tide, and the whole city’s morning. And all to put off a single sunrise in one small room on Spindle Street.' },
        { kind: 'line', who: 'marigold', text: 'I should like very much to hate him. I find I cannot quite manage it. I have sat by a bed too, you know. Not a child’s. But I know the arithmetic.' },
        { kind: 'line', who: 'evangeline', text: 'And Colette? Is she — is she still there? In that room? For a whole year?' },
        { kind: 'line', who: 'odile', text: 'If he has held the night, then he has held her in it. Exactly as she was at one minute to midnight. Neither better nor worse. Neither going nor staying.' },
        { kind: 'line', who: 'wren', text: 'Then she’s waiting too. Like the sea.' },
        { kind: 'narrate', text: 'Lucien had gone to the tide-clock. It stood against the wall of the lamp room, a tall brass case like a grandfather clock with a moon-dial in its face. Inside the glass the new mechanism glittered, finer than anything else in the room, precise as lace. Its single hand stood at the bottom of the ebb.' },
        { kind: 'line', who: 'ichabod', text: 'It’s beautiful. That’s the worst of it. It’s the most beautiful thing in the lighthouse.' },
        { kind: 'line', who: 'wren', text: 'Can you move it?' },
        { kind: 'line', who: 'ichabod', text: 'Not with my hands. It isn’t a clock you wind — it’s a clock you keep. Brine kept it for him. Brine’s gone.' },
        { kind: 'line', who: 'ichabod', text: '…Which means nobody is keeping it any more. Which means it is only holding the sea out of habit. And the sea, Keeper, has had a great deal of practice at breaking habits.' },
        { kind: 'narrate', text: 'He turned his back on the clock. He went to the broken window of the lamp room and leaned out into the fog, high over the black water, and held his hands out over the sea the way they had first seen him on the north wall — palms down, fingers spread.' },
        { kind: 'line', who: 'wren', text: 'Valerian, Columbine. The lens. Turn it.' },
        { kind: 'narrate', text: 'The lens was taller than a man and heavier than a carriage. It took the two of them on the crank, Aveline’s ribbons in the gearing, and Corvin’s shoulder against the frame. It turned an inch. A foot. Then something in the base gave a sigh, and the great glass came round on its rail and faced the sea.' },
        { kind: 'narrate', text: 'Corvin set the Lantern down inside the empty lamp-housing.' },
        { kind: 'narrate', text: 'The beam went out across the water — gold, not black. It struck the fog and the fog lit like a cloud at sunset. It reached the bar, and past the bar, and found the hulls of eleven ships sitting dark on the flat sea, and laid a long bright road from each of them to home.', tone: 'warm' },
        { kind: 'line', who: 'ichabod', text: 'Come on. Come on. You know me. You have known me since I was four.' },
        { kind: 'line', who: 'ichabod', text: 'I called you once for nothing but a ship with three tall funnels and a band on deck. You came. You always came. And she went out.' },
        { kind: 'line', who: 'ichabod', text: 'I do not call you for myself tonight. I call you for eleven ships; a boy who never left the wall; a supper kept three hundred nights. Come in.' },
        { kind: 'line', who: 'ichabod', text: 'Please. Not for me. For them.' },
        { kind: 'narrate', text: 'In the tide-clock’s case, with a sound like a small bone breaking, the lace-fine mechanism slipped one tooth.' },
        { kind: 'narrate', text: 'Behind them, for the first time in a year, the sea moves. One wave. Then another. The tide is coming in.', tone: 'dawn' },
        { kind: 'bg', bg: 'docks', tone: 'dawn' },
        { kind: 'narrate', text: 'It came in the way breath comes back to someone pulled from deep water — in one great shuddering gasp. It filled the bowl of the harbour from the bar to the Fishgate Stairs. It lifted the coal barge and the keel-up dinghies. It found the ships lying on their sides in the mud, and set them, very gently, upright.' },
        { kind: 'narrate', text: 'Under the sunken pier it lifted the drowned lanterns off the mud — every one, every name — and carried them, still burning, out along the wall, past the lighthouse, over the bar: a mile-long river of small lights going out to sea one year late.' },
        { kind: 'narrate', text: 'Nobody on the breakwater could speak. So Aveline sang instead, very softly, the old wall-song, and after the first line Lucien sang it with her.' },
        { kind: 'narrate', text: 'Float out, float out, my paper light,\nfloat out across the bar,\nand tell the ones the sea has kept\nwe know just where they are.' },
        { kind: 'line', who: 'ichabod', text: 'There she goes. There she goes, Maman. Quarter past twelve. Only a year behind.' },
        { kind: 'line', who: 'ichabod', text: '“Till the tide forgets to turn — and that will be no day.” We sang it every year. And it did forget, for a whole year it forgot. And the wall stayed anyway.' },
        { kind: 'narrate', text: 'Out past the bar, in the gold road of the beam, a ship’s lamps came on. Then another. Then another. Somewhere a man laughed aloud across the water — a big, astonished laugh, the laugh of someone who has woken from a dream of drowning and found himself merely wet.' },
        { kind: 'bell', strokes: 8, text: 'Eight bells rang out across the harbour — the end of the long watch.' },
        { kind: 'narrate', text: 'Then a horn: two short notes and a long one. And from the end of the north wall, high and cracked and furious with joy, a boy’s voice shouting a trawler’s name and number over and over, as if the sea might still forget it.' },
        { kind: 'line', who: 'Tam Hollis', text: 'KITTIWAKE! VM 41! DAD! DAD, I’M HERE! I DIDN’T GO! I DIDN’T GO ANYWHERE!' },
        { kind: 'narrate', text: 'Lucien stood at the window and counted them in, aloud, one by one, as the keeper had asked. The Kittiwake. The Annabel Lee, a quarter of her belonging to a count in crimson who wept quite openly to see her. The Morwenna. The Mary Penhallow. Eleven. Eleven in.' },
        { kind: 'narrate', text: 'He wrote it in the logbook, in his upright tide-table hand, beneath the last entry, on the first clean line the book had seen in a year: Ships counted in: 11. Lamp turned to sea. Keeper relieved.' },
        { kind: 'line', who: 'evangeline', text: 'The doves. Look — oh, look at them go.' },
        { kind: 'narrate', text: 'From the roof of the mission the whole white flock had risen into the beam and was streaming out towards the ships, each bird with a curl of paper on its leg. Letters from wives. From children. From a woman on Ropewalk Row who had kept a man’s supper warm for three hundred and sixty-five nights.' },
        { kind: 'narrate', text: 'Corvin opened his satchel on the chart table. Every salt-swollen envelope inside it — every letter addressed to a ship — had dried; the run ink had crept back into its lines, and the smeared addresses had sharpened into names.' },
        { kind: 'line', who: 'wren', text: 'They can be delivered now. Every one of them.' },
        { kind: 'line', who: 'wren', text: 'Ropewalk Row first, I think. Somebody ought to tell Bet she can trust the harbour light again.' },
        { kind: 'line', who: 'odile', text: 'You look like a man who has just been handed a very great deal of work.' },
        { kind: 'line', who: 'wren', text: 'I look like a postman, Seraphine. It’s the happiest a postman ever looks.' },
        { kind: 'narrate', text: 'In the window of the harbourmaster’s office, at the root of the north wall, a lamp burned steady and true. Beside it a big man stood with his forehead to the glass, watching the boats come in, saying one word over and over, softly, as if he might wear it into the pane: Margot. Margot. Margot.' },
        { kind: 'narrate', text: 'Overhead the stars had not moved. The sky was still the sky of one minute past midnight, fixed and patient as a painting. But under it, for the first time in a year, something in Vellmoor was keeping time again. The sea, breathing. In. And out.' },
        { kind: 'line', who: 'odile', text: 'It is not the morning, Corvin. Do not mistake it. It is only the sea remembering that a morning is owed.' },
        { kind: 'line', who: 'wren', text: 'Then the sea and I have something in common.' },
        { kind: 'narrate', text: 'Across the harbour, high on the hill above the old town, the Cathedral Clock stood black against the frozen stars. The lighthouse beam swept across it once, and for an instant they saw its great face — and the empty place in the middle where the hands should be.' },
        { kind: 'line', who: 'bastian', text: 'He’s up there. Isn’t he. With her.' },
        { kind: 'line', who: 'wren', text: 'I think so.' },
        { kind: 'line', who: 'bastian', text: 'Corvin. When we find him… will he know me?' },
        { kind: 'line', who: 'wren', text: 'He’ll know you. He made you with his own hands; a man doesn’t forget his own hands. The question isn’t whether he knows you, Columbine. It’s whether he’s earned the right to.' },
        { kind: 'line', who: 'ichabod', text: 'I’m coming with you. The sea’s in. It can spare me. And I want to look in the eye the man who made an old keeper choose between the living and the drowned.' },
        { kind: 'line', who: 'evangeline', text: 'So am I. The door’s open behind me. The doves know the way home without me now.' },
        { kind: 'narrate', text: 'Corvin touched the satchel at his hip, where the two letters lay — a child’s envelope addressed to whoever stops the clock, and a father’s card meant for first light. Undelivered, both of them. Both of them, he thought, going to the same house.' },
        { kind: 'line', who: 'wren', text: 'Then we go to the clock.' },
        { kind: 'narrate', text: 'Behind them the Breakwater Light turned, slow and gold and patient, over a sea that was moving again — and far out on the water, on the long road the beam laid down, the last of the paper lanterns went on burning, one year late, all the way to the edge of the world.', tone: 'dawn' },
      ],
    },
  ],

  interludes: {
    '3-1': 'ch3_i1',
    '3-2': 'ch3_i2',
    '3-4': 'ch3_i3',
    '3-5': 'ch3_i4',
    '3-6': 'ch3_i5',
  },

  intros: {
    '3-1': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'This was the inner basin. Forty feet of water at high tide, once. You could drop a stone off the north wall and count to three before it touched bottom.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'Now you could drop a stone and it would just sit there and look at you.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Quite. Mind the ribs in the mud — those are the old currents. They stopped where they were, the way a tablecloth keeps its creases after the feast.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'My shoes were made in Milan by a man who wept when he finished them. I should like it noted that I am walking into a harbour in them.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Noted. Seraphine, the sky?' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'The same as always. Every star exactly where it was at midnight. But look down — the puddles have them too. It is like walking across a broken mirror of heaven.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The harbour lights went out first. Every ship out there is sailing blind.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Then we light the way home, one pier at a time.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'There are birds on the masts. Lots of them. Why are they so still?' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Those aren’t birds any more. The gulls followed the boats out every night for scraps. When the boats didn’t come back, the gulls kept waiting. The Dimming found them waiting.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Hunger that has forgotten what it was hungry for. Be careful — it will take whatever is nearest.' },
      { speaker: 'Gull Wraith', text: 'Mine! Mine! Mine! Mine!' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Lantern up. Stay close to the light, and keep to the hard mud.' },
    ],
    '3-2': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The fish market. On New Year’s Eve it was the loudest place in Vellmoor. Every stall open till midnight, everyone buying for the morning.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'The fish look remarkably well for their age. I know actresses who would kill for that complexion.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'There’s a woman behind that stall. She’s holding out a herring wrapped in paper. She has been holding it out for a year, hasn’t she?' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Old Wenna Trewin. She gave me a sprat for luck every Saturday until I was fifteen. She’s waiting for somebody to pay.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Then someone will. Later. Not yet.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Hush. Do you hear it? Under the dripping. Someone is humming.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Cover your ears if that song starts. It knows your name.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The sirens sing in the voices of the drowned. Don’t answer — whatever they say.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'What if it is someone we know?' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Then especially don’t answer.' },
      { speaker: 'Fog Siren', text: 'Who’s that out on the wall so late, with the water gone so low? Come in, love. Come in off the wall. Your supper’s on.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: '…' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'Lucien. Lucien, I have your sleeve. I am not letting go of your sleeve.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Everyone, to me. Sing back if you have to. Anything — a hymn, a nursery rhyme. Just don’t give it silence to fill.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'At last. A use for forty years of comic opera.' },
    ],
    '3-3': [
      { speaker: 'Aveline', portrait: 'evangeline', text: 'The crane yard. I could see these from the dovecote. Every night, the same — the cranes swinging slowly, loading nothing onto ships that aren’t there.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The night shift. They were halfway through unloading the Grace Darling’s cargo when midnight came. They’re still unloading it.' },
      { speaker: 'Night Shift', text: 'Heave, and lower. Lower, and heave. We’re paid when the bell has done. Heave, and lower. Lower, and heave. And the bell is never done.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'They have no faces.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Dock work is like that. Nobody looks at a stevedore’s face. The Dimming only finished the job.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Lucien. You have gone quiet. Quieter than usual.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Keeper Brine taught me to read the tide tables. He loved this sea more than anything. Whatever is out there now isn’t him.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'That page on Aveline’s dove — “Mr. V.” He liked nobody and trusted nobody. If he let a stranger into his lamp room, it was because he thought it would keep the ships safe. I would bet my life on it.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'Then don’t. Bet something smaller. Bet a boiled sweet.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: '…How do you know about the sweets?' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'He used to save my doves crusts on his windowsill. A man who does that saves other things too.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'The cranes are turning towards us.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'They always do, when one is the most interesting thing in the yard. Shall we?' },
    ],
    '3-4': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The customs house. Everything that came into Vellmoor by sea went through here and got a stamp on it. Brandy, silk, oranges, tea. Me, once, when I was six and stowed away on a coal boat for an afternoon.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'What duty did they charge on you?' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'One clip round the ear, payable to my mother.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'The windows are glowing. Green. Like the sea used to on summer nights, when the water was warm and every oar left a trail of light.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'Crates of confiscated fireflies. Someone has been hoarding the light.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Not hoarding. Look how they’re stacked. Each crate padded with straw. Air-holes drilled by hand. Whoever packed these wanted every single one of them to live.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Stamped and sealed by order of… “A. Vire, Master Clockmaker”?' },
      { speaker: 'Corvin', portrait: 'wren', text: 'A. V.' },
      { speaker: 'Columbine', portrait: 'bastian', text: '…' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Columbine?' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'Nothing. It’s nothing. Something’s moving between the crates. Let’s deal with that first.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Lamp-Eaters. They have been feeding on the glow through the slats all year. They will not want to share.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Then let’s open the lids. All of them.' },
    ],
    '3-5': [
      { speaker: 'Corvin', portrait: 'wren', text: 'The fireflies are settling here. All along the old pier. As if they’ve found something they recognise.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The sunken pier. It went down in the great storm of ’04 — the end of it, anyway. At low water the planks stand up out of the mud like the ribs of a whale.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Beneath the planks… lanterns. Thousands of them, drowned.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The Lantern Tide. They’re still here. All this time I thought they had made it out. I thought at least they had gone where they were meant to go.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'Lucien. Are you all right?' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'There’s one of mine under there. Under the eleventh piling. I would know where it fell — I watched which way the current set before it stopped.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'Then we shall fetch it for you, my boy. Whatever stands in the way.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'Something is standing in the way. Quite a lot of somethings.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The shades from the crane yard. They’ve followed us. And the gulls — they’re picking at the lanterns. Pulling the names off them.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Not tonight. Not one more name. Everyone — keep them away from the pier.' },
    ],
    '3-6': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The breaker’s yard. Where ships come to be taken apart when they’re too old to sail. You can see the breakwater from here — it starts just past the last hull.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'Everything here is rusting. Look — you can watch it creep. I thought nothing could change since midnight.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Not change. Fall. The Dimming does not let things grow, but it is very happy to let them wear away.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'An apt description of most theatre critics.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'The fog is thicker. And it’s… angry? Can fog be angry?' },
      { speaker: 'Corvin', portrait: 'wren', text: 'They are getting desperate. Brine is close.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The beam is passing right over us now. Every time it does, the Dimmed get bolder. As if the dark were being poured into them.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'It is. The lamp is feeding them. Do not stand in the beam longer than you must.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'I’ll keep the water between us and the worst of it. Stay inside the ribbons if you can.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'There’s Brine’s net-loft, at the root of the wall. If we get there, we can rest. He always kept the stove laid.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Then that is where we’re going. Through the rust. Quickly.' },
    ],
    '3-7': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The breakwater. A mile of granite, laid by hand, one block at a time, in 1811. Two hundred men built it. Eleven of them drowned doing it. Their names are on a plaque at the far end.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'There is water on both sides of us now. Only it isn’t water. It’s just… more dark.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'My doves won’t come any further. They’re circling back to the mission. They’ve never refused me before.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Animals know when a light is lying.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'The lighthouse is shining. But it is shining black.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'When I was small I used to walk out here at dusk and wait for him to light it. I’d count. He always lit it on the forty-ninth second after sunset. Never the forty-eighth. Never the fiftieth.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'A man after my own heart. Curtain up on the dot, or not at all.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Something’s falling from the gallery. Bottles.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'He’s throwing them. He’s still throwing them — “keep away, keep away.” Even now.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'Then he is still in there. Hold on to that.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Sorry, Mr. Brine. We’re not very good at keeping away. Forward.' },
    ],
    '3-8': [
      { speaker: 'Lucien', portrait: 'ichabod', text: 'One hundred and forty stairs to the lamp room. I used to run them. He used to shout that I’d break my neck, and then time me.' },
      { speaker: 'Aveline', portrait: 'evangeline', text: 'It’s so cold in here. Not the cold of the sea. The cold of a room nobody has spoken in.' },
      { speaker: 'Columbine', portrait: 'bastian', text: 'There’s a clock up there. I can hear it. Tick… and no tock. Tick… and no tock.' },
      { speaker: 'Keeper Brine', text: 'Ships kept breaking on my rocks in the dark, so I taught the light to hide them. Kinder, isn’t it? Nothing sails. Nothing sinks.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'Keeper, it’s me. Lucien. You taught me the tides.' },
      { speaker: 'Keeper Brine', text: 'There are no tides, boy. The clockmaker bought them. He paid me in a night that never ends.' },
      { speaker: 'Keeper Brine', text: 'Eleven out there. Eleven safe. No one goes on the rocks while I keep watch. No one. Not ever again. Not on my light.' },
      { speaker: 'Lucien', portrait: 'ichabod', text: 'They’re not safe, keeper. They’re fading. Their bells are getting quieter every night. You aren’t keeping them. You’re keeping them from coming home.' },
      { speaker: 'Keeper Brine', text: 'Home is where the rocks are, lad. I’ve seen what home does to a boat.' },
      { speaker: 'Seraphine', portrait: 'odile', text: 'He cannot hear you yet. The fog is too thick in him. We must clear it first.' },
      { speaker: 'Valerian', portrait: 'marigold', text: 'Then let us be the weather, for once.' },
      { speaker: 'Corvin', portrait: 'wren', text: 'Turn the lamp around, keeper. Or we will do it for you.' },
    ],
  },

  outros: {
    '3-1': 'A trawler sounds its horn somewhere out in the fog — two short notes and a long one. Someone has seen the light.',
    '3-2': 'The market stalls drip with fog, and nothing sings any more. Old Wenna Trewin still holds out her herring, but her eyes have begun, very slightly, to blink.',
    '3-3': 'A crane swings loose and comes to rest with its hook pointing, like an accusing finger, straight at the lighthouse.',
    '3-4': 'The crates burst open. The fog glows green for a mile — and every ledger in the customs house bears the same signature.',
    '3-5': 'The drowned lanterns flicker, one by one, like eyes opening on a name.',
    '3-6': 'Rust flakes off the cranes like old paint off a memory. Ahead, at the root of the breakwater, a stovepipe is waiting with the fire laid.',
    '3-7': 'At the end of the breakwater the lighthouse door creaks open on its own. Inside, a stair climbs into the dark, and somewhere at the top of it a clock goes tick, and never tock.',
    '3-8': 'The lighthouse beam swings back out to sea — gold now, not black. Far out in the dark, a ship turns for home.',
  },
};
